import {adSettings} from './ad-catalog.js?v=16';
export function installAdInspector(getSystem){
 const dialog=document.createElement('dialog');dialog.id='adInspector';dialog.innerHTML=`<div class="ad-head"><h2>Advertising · developer</h2><button id="adClose" aria-label="Close advertising inspector">×</button></div><p class="ad-note">Archival environmental artwork. No brand sponsors or endorses NightView. Placement is fictional; no Street View imagery is used.</p><label class="ad-toggle"><input id="adEnabled" type="checkbox" checked> Real-brand layer</label><label>Authored advertising surfaces<select id="adSurface"></select></label><div class="ad-preview"><figure><img id="adOriginal" alt="Original authored surface or source artwork"><figcaption>Original surface / source</figcaption></figure><figure><img id="adEnhanced" alt="Enhanced advertisement preview"><figcaption>Enhanced content preview · scene shader adds cracks and occlusion</figcaption></figure></div><dl id="adDetails"></dl><label>Weathering<input id="adWeather" type="range" min="0" max="1" step="0.05"></label><label>Illumination override<select id="adState"><option value="auto">Automatic environmental policy</option value="physical">Physical / unlit</option><option value="dark">Dark</option><option value="shattered">Shattered</option><option value="frozen">Unlit retained frame</option><option value="corrupted">Corrupted fragments</option><option value="flicker">Intermittent flicker</option><option value="powered">Powered · developer override</option></select></label><p class="ad-note">Sources and usage basis: <a href="assets/ads/manifest.json" target="_blank" rel="noopener">asset manifest</a>. LOD uses mipmaps and distance culling. The preview is an approximation; sunlight, shadows and ivy are applied in the scene.</p>`;document.body.append(dialog);
 const $=id=>document.getElementById(id),button=document.createElement('button');button.id='adInspect';button.textContent='Advertising inspector';document.querySelector('.options-links').append(button);let selected='',system=null;
 try{adSettings.enabled=localStorage.getItem('nightview-real-brands')!=='off';}catch{}
 function details(){const sys=getSystem();if(!sys)return;const records=sys.snapshot();if(sys!==system){system=sys;selected=records[0]?.id||'';$('adSurface').replaceChildren(...records.map(r=>{const o=document.createElement('option');o.value=r.id;o.textContent=r.id+' · '+r.kind;return o;}));}if(!selected)return;const r=records.find(r=>r.id===selected);if(!r)return;$('adSurface').value=selected;$('adEnabled').checked=adSettings.enabled;
 const lines={Surface:r.id+' · '+r.kind,Detection:'Authored mesh metadata; no image detection',Original:r.original,Advertisement:r.asset,Company:r.brand,Source:r.source||'Original procedural artwork',Usage:r.license+' · '+r.status,Context:r.relevance,Illumination:r.state+' · '+r.power,LOD:r.lod+' · '+r.distance+' m',Asset:r.loaded?'Ready':'Loading / fictional placeholder',Weathering:Math.round(r.weather*100)+'%'};
 $('adDetails').replaceChildren(...Object.entries(lines).flatMap(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;if(k==='Source'&&r.source){dd.textContent='';const a=document.createElement('a');a.href=r.source;a.target='_blank';a.rel='noopener';a.textContent='Source and rights record';dd.append(a);}return [dt,dd];}));
 $('adWeather').value=r.weather;const record=sys.records.find(x=>x.id===selected);$('adState').value=record.override||'auto';$('adOriginal').src=sys.preview(selected,true);$('adEnhanced').src=sys.preview(selected);}
 button.onclick=()=>{system=null;details();dialog.showModal();};$('adClose').onclick=()=>dialog.close();$('adSurface').onchange=e=>{selected=e.target.value;details();};$('adEnabled').onchange=e=>{getSystem()?.setEnabled(e.target.checked);try{localStorage.setItem('nightview-real-brands',e.target.checked?'on':'off');}catch{}details();};$('adWeather').oninput=e=>{getSystem()?.configure(selected,{weather:Number(e.target.value)});details();};$('adState').onchange=e=>{getSystem()?.configure(selected,{state:e.target.value});details();};setInterval(()=>{if(dialog.open)details();},1500);
}
